style.css:
@-moz-document domain("google.com"), domain("www.google.com") {
/* Genel tema */
  :root {
    --old-blue: #0000cc;
    --old-green: #006600;
    --old-grey: #666666;
    --bg: #ffffff;
    --text: #000000;
    --visited: #551a8b;
  }

  html, body {
    background: var(--bg) !important;
    color: var(--text) !important;
    font-family: Arial, Helvetica, sans-serif !important;
    font-size: 14px !important;
  }

  /* Arama kutusu minimal */
  form[role="search"] input[type="text"],
  input[aria-label="Search"],
  textarea {
    border: 1px solid #b3b3b3 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    height: 32px !important;
    padding: 4px 8px !important;
  }

  /* Butonlar klasik */
  input[type="submit"], button {
    background: #f2f2f2 !important;
    color: #000 !important;
    border: 1px solid #b3b3b3 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    padding: 6px 10px !important;
  }

  /* Logo hizalama ve boşluklar */
  #searchform, form[role="search"] {
    margin-top: 16px !important;
  }

  /* Sonuç listesi tek sütun, kutusuz */
  #search, #center_col, #rcnt {
    max-width: 980px !important;
    margin: 0 auto !important;
  }

  /* Kart, panel, modern gölgeleri kaldır */
  *, *::before, *::after {
    box-shadow: none !important;
    border-image: none !important;
    backdrop-filter: none !important;
  }

  /* Sonuç öğeleri (yeni Google: .g, .MjjYud blokları) */
  .g, .MjjYud, .hlcw0c, .bkWMgd, .Ww4FFb {
    border: none !important;
    padding: 0 !important;
    margin: 14px 0 !important;
    background: transparent !important;
  }

  /* Başlık linkleri mavi, alt çizgili */
  a:link h3, h3 a:link,
  .vJt8c h3, .LC20lb {
    color: var(--old-blue) !important;
    text-decoration: underline !important;
    font-weight: normal !important;
  }
  a:visited h3, h3 a:visited,
  .LC20lb:visited {
    color: var(--visited) !important;
  }

  /* Yeşil URL (eski görünüm) */
  .TbwUpd, .NJo7tc, cite, .byrV5b {
    color: var(--old-green) !important;
    font-style: normal !important;
  }

  /* Açıklama metni gri ton */
  .IsZvec, .VwiC3b, .MUxGbd, .aCOpRe, .st {
    color: var(--old-grey) !important;
    line-height: 1.4 !important;
  }

  /* Üst menü sade (Tümü, Görseller, Videolar...) */
  .cS4Vcb, .MUFPAe, .hdtb-mitem, .IUO5Yd, .hdtbU {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
  }
  .hdtb-mitem a, .hdtbU a, .NZmxZe {
    color: #000 !important;
    text-decoration: none !important;
    padding: 0 8px !important;
  }

  /* Kenar panel ve bilgi kutuları kapatma/ sadeleştirme */
  .kp-blk, .wDYxhc, .ULSxyf, .rhs, #rhs {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
  }

  /* Favicon, site adları ve ekstra rozetler minimal */
  .xA4EIc, .Z26q7c, .G1zzid, .GgE5Kf, .CuS8oc, .h3pQ1b {
    display: none !important;
  }

  /* “İlgili aramalar” ve alt bölümler sade */
  .MgUeAb, .TQc1id, .V7XJQb, .YFf8T {
    border: none !important;
    background: transparent !important;
  }

  /* Görseller sayfasını basitleştir (grid kenarlık yok) */
  .isv-r, .S4w1l {
    border: 1px solid #e5e5e5 !important;
    border-radius: 0 !important;
    background: #fff !important;
  }

  /* Karanlık modu kapatmaya zorla */
  html[dark], body[dark], [data-darkreader-scheme] {
    filter: none !important;
    color-scheme: light !important;
  }
}
